    elif e == x:
        s = SubsSet()
        return (s, s[x])
    elif e.is_Mul or e.is_Add:
        i, d = e.as_independent(x)
        if d.func != e.func:
            s, expr = mrv(d, x)
            return (s, e.func(i, expr))
        a, b = d.as_two_terms()
        s1, e1 = mrv(a, x)
        s2, e2 = mrv(b, x)
        return mrv_max1(s1, s2, e.func(i, e1, e2), x)
    elif e.is_Pow and e.base != S.Exp1:
        e1 = S.One
        while e.is_Pow:
