            e1 *= e.exp
            e = b1
        if b1 == 1:
            return (SubsSet(), b1)
        if e1.has(x):
            return mrv(exp(e1 * log(b1)), x)
        else:
            s, expr = mrv(b1, x)
            return (s, expr ** e1)
    elif isinstance(e, log):
