            return mrv(e.exp.args[0], x)
        li = limitinf(e.exp, x)
        if any((_.is_infinite for _ in Mul.make_args(li))):
            s1 = SubsSet()
            e1 = s1[e]
            s2, e2 = mrv(e.exp, x)
            su = s1.union(s2)[0]
            su.rewrites[e1] = exp(e2)
            return mrv_max3(s1, e1, s2, exp(e2), su, e1, x)
        else:
            s, expr = mrv(e.exp, x)
            return (s, exp(expr))
