        if (syncSession == null) {
            RealmLog.error("Matching Java SyncSession could not be found for: " + sessionPath);
        } else {
            try {
                return syncSession.getAccessToken(authServer, refreshToken);
            } catch (Exception exception) {
                RealmLog.error(exception);
            }
        }
        return null;
    }

